SELECT

FROM orders
WHERE reservation_id = #{reservationId}
  AND user_id = #{userId}
  AND status IN ('PENDING', 'PAID')

SELECT

FROM orders
WHERE id = #{id}
  AND user_id = #{userId}

SELECT COUNT(*)
FROM orders
WHERE user_id = #{userId}

SELECT

FROM orders
WHERE user_id = #{userId}
ORDER BY created_at DESC, id DESC
LIMIT #{limit}
OFFSET #{offset}
